function cr(el){const fg=parse(getComputedStyle(el).color).slice(0,3);const b=bg(el);const a=lum(fg),c=lum(b);return {fg:getComputedStyle(el).color,bg:b.join(','),ratio:((Math.max(a,c)+0.05)/(Math.min(a,c)+0.05)).toFixed(2),fs:getComputedStyle(el).fontSize,fw:getComputedStyle(el).fontWeight};}
const r={};
r.filterTag = cr(document.querySelector('.br-tag.interaction .text-gray-50'));
